// spec: specs/delivery.md §14 · кейс .qa/tests/delivery/dlv-18-delivery-note-print-totals-row.md · seed: tests/seed.admin.spec.ts
// #787114 (עבר QA 19.11): печатная תעודת משלוח (emulateMedia print, A4-раскладка pd-table) — итоговая строка tfoot:
//   «סה״כ שורות: N | סה״כ פריטים | <кол-во> | סה״כ לתשלום | ₪<сумма>». Подпись количества стоит вплотную к количеству
//   (под «כמות»), сумма подписана «סה״כ לתשלום» (под «סה״כ»); «סה״כ פריטים» НЕ рядом с суммой ₪. Штрихкоды под позициями остаются (#f43d23).
// Данные — существующие заказы, только чтение: #504 (4 позиции, ₪1,042.00), #685 (1 позиция). Печать браузера не вызывается → @prod-safe.
// Замеры: getBoundingClientRect ячеек tfoot и th; порядок справа налево по центру ячейки.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const NOTES = { 504: '6f797bf5-1ef8-44eb-8ad5-073e0b0f341e', 685: 'a6f2f8c0-6d4d-4a8b-a03f-44f041778a3d' } as const;
const BIDI = /[‎‏‪-‮⁦-⁩]/g;
const money = (n: number) => '₪' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

async function openPrint(page: Page, no: keyof typeof NOTES) {
  await page.goto(`/delivery/${NOTES[no]}`);
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('svg[data-barcode]').first()).toBeAttached({ timeout: 20_000 });
  await page.emulateMedia({ media: 'print' });
  await expect(page.locator('table.pd-table')).toBeVisible();
}

/** Печатная таблица: шапка, строки товаров, ячейки tfoot с геометрией. */
const measure = (page: Page) => page.evaluate(() => {
  const strip = (s: string) => s.replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
  const t = document.querySelector('table.pd-table') as HTMLTableElement;
  const box = (e: Element) => { const r = e.getBoundingClientRect(); return { l: r.left, r: r.right, cx: r.left + r.width / 2, t: r.top, b: r.bottom }; };
  const ths = [...t.tHead!.rows[0].cells];
  const foot = [...t.tFoot!.rows[0].cells];
  const lines = [...t.querySelectorAll('tbody.pd-line')].map((b) => {
    const first = (b as HTMLTableSectionElement).rows[0];
    const range = document.createRange();
    range.selectNodeContents(first.cells[1]);
    const skuText = first.cells[1].firstChild ? (() => { const r = document.createRange(); r.selectNodeContents(first.cells[1].firstChild!); return r.getBoundingClientRect(); })() : range.getBoundingClientRect();
    const svgs = [...b.querySelectorAll('svg[data-barcode]')].filter((s) => (s as SVGElement).checkVisibility());
    return {
      name: strip(first.cells[0].textContent || ''), qty: strip(first.cells[2].textContent || ''), total: strip(first.cells[4].textContent || ''),
      svgs: svgs.length, svgTop: svgs[0] ? svgs[0].getBoundingClientRect().top : null, skuBottom: skuText.bottom,
    };
  });
  return {
    heads: ths.map((h) => ({ text: strip(h.textContent || ''), ...box(h) })),
    foot: foot.map((c) => ({ text: strip(c.textContent || ''), ...box(c) })),
    lines,
    below: strip(document.body.innerText),
  };
});

async function checkTotalsRow(page: Page, no: keyof typeof NOTES) {
  await openPrint(page, no);
  const m = await measure(page);
  const qty = m.lines.reduce((s, l) => s + Number(l.qty), 0);
  const sum = m.lines.reduce((s, l) => s + Number(l.total.replace(/[^\d.]/g, '')), 0);

  expect(m.foot.map((c) => c.text), 'tfoot: 5 ячеек в порядке чтения (RTL)').toEqual([
    `סה״כ שורות: ${m.lines.length}`, 'סה״כ פריטים', String(qty), 'סה״כ לתשלום', money(sum),
  ]);
  const [rows, itemsLabel, qtyCell, payLabel, amount] = m.foot;
  // визуально справа налево: «סה״כ שורות» → «סה״כ פריטים» → кол-во → «סה״כ לתשלום» → ₪ (центры строго убывают)
  const cxs = [rows, itemsLabel, qtyCell, payLabel, amount].map((c) => c.cx);
  for (let i = 1; i < cxs.length; i++) expect(cxs[i], `ячейка ${i} левее ячейки ${i - 1}`).toBeLessThan(cxs[i - 1]);

  // количество — в колонке «כמות», сумма — в колонке «סה״כ»; «סה״כ פריטים» — до количества, а не между «סה״כ לתשלום» и ₪
  const head = (name: string) => m.heads.find((h) => h.text === name)!;
  expect(qtyCell.cx, 'количество под «כמות»').toBeGreaterThanOrEqual(head('כמות').l);
  expect(qtyCell.cx).toBeLessThanOrEqual(head('כמות').r);
  expect(amount.cx, 'сумма под «סה״כ»').toBeGreaterThanOrEqual(head('סה״כ').l);
  expect(amount.cx).toBeLessThanOrEqual(head('סה״כ').r);
  expect(itemsLabel.l - qtyCell.r, '«סה״כ פריטים» вплотную к количеству (≤ 40px)').toBeLessThanOrEqual(40);
  expect(payLabel.l - amount.r, '«סה״כ לתשלום» вплотную к сумме (≤ 40px)').toBeLessThanOrEqual(40);
  expect(itemsLabel.l - amount.r, '«סה״כ פריטים» не рядом с суммой ₪').toBeGreaterThan(80);
  expect(itemsLabel.cx).toBeGreaterThan(amount.cx);

  // под таблицей остаются «סה״כ פריטים: N» и «סה״כ לתשלום: ₪…»
  expect(m.below).toContain(`סה״כ פריטים: ${qty}`);
  expect(m.below).toContain(`סה״כ לתשלום: ${money(sum)}`);
  return { m, qty, sum };
}

test.describe('תעודת משלוח בהדפסה — שורת הסיכום (#787114)', () => {
  test('#504: «סה״כ שורות: 4 | סה״כ פריטים | 4 | סה״כ לתשלום | ₪1,042.00» — «סה״כ פריטים» צמוד לכמות, לא לסכום #787114 @desktop @prod-safe', async ({ page }) => {
    const { m, qty, sum } = await checkTotalsRow(page, 504);
    expect(m.lines.length).toBe(4);
    expect(qty).toBe(4);
    expect(money(sum)).toBe('₪1,042.00');
    expect(m.foot.map((c) => c.text.replace(BIDI, ''))).toEqual(['סה״כ שורות: 4', 'סה״כ פריטים', '4', 'סה״כ לתשלום', '₪1,042.00']);
  });

  test('#685 (שורה אחת): אותה שורת סיכום — «סה״כ שורות: 1», כמות וסכום מסומנים בנפרד #787114 @desktop @prod-safe', async ({ page }) => {
    const { m } = await checkTotalsRow(page, 685);
    expect(m.lines.length).toBe(1);
    expect(m.foot[0].text).toBe('סה״כ שורות: 1');
  });

  test('#504: ברקוד אחד מתחת לכל פריט (רגרסיה #f43d23) #787114 #f43d23 @desktop @prod-safe', async ({ page }) => {
    await openPrint(page, 504);
    const m = await measure(page);
    expect(m.lines.length).toBe(4);
    for (const l of m.lines) {
      expect(l.svgs, `ברקוד אחד בשורה «${l.name}»`).toBe(1);
      expect(l.svgTop!, `ברקוד מתחת למק"ט בשורה «${l.name}»`).toBeGreaterThanOrEqual(l.skuBottom - 1);
    }
  });
});
